#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[4][4], r[4][4];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            plik >> m[i][j];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            r[i][j] = m[3 - j][i];
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            if (j > 0) cout << " ";
            cout << r[i][j];
        }
        cout << endl;
    }
    int stale = 0;
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            if (m[i][j] == r[i][j]) stale++;
    cout << "Stale elementy: " << stale << endl;
    cout << "Sumy wierszy:";
    for (int i = 0; i < 4; i++) {
        int s = 0;
        for (int j = 0; j < 4; j++) s += r[i][j];
        cout << " " << s;
    }
    cout << endl;
    return 0;
}
```

